-- Kafa'a schema: every kafaa_* table
-- GENERATED by scripts/gen-schema.mjs from src/data/schema.ts. Do not edit by hand: change the schema and run `npm run gen`.
-- Additive only: creates kafaa_* objects; never alters or drops existing NEXUS objects.

create table if not exists kafaa_schema_version (id int primary key, generated_at timestamptz not null default now(), tables int not null);
alter table kafaa_schema_version enable row level security;
drop policy if exists kafaa_read on kafaa_schema_version;
create policy kafaa_read on kafaa_schema_version for select to anon, authenticated using (true);
grant select on kafaa_schema_version to anon, authenticated;

-- M09 · Organisations: ENEC entities, partners, suppliers, universities, regulators
create table if not exists kafaa_organisations (
  id text primary key,
  name_en text not null,
  name_ar text not null,
  short text,
  kind text not null check (kind in ('group_entity', 'shareholder', 'supplier', 'partner', 'university', 'international', 'regulator', 'government', 'finance', 'offtaker', 'emergency', 'research', 'observer_org')),
  category text not null check (category in ('ownership', 'design_build', 'om_support', 'fuel', 'advanced_rd', 'international_operators', 'local_supply_offtake', 'finance', 'education_workforce', 'technology_government', 'emergency_response', 'oversight', 'synthetic')),
  categories text[] not null default '{}'::text[],
  rel_types text[] not null default '{}'::text[],
  relationship_en text not null default '',
  relationship_ar text not null default '',
  status text not null default 'active' check (status in ('active', 'historic', 'exploratory')),
  dates text not null default '',
  country text,
  binding boolean,
  public_listed boolean not null default false,
  synthetic boolean not null default false,
  nexus_org_id text,
  icv_score numeric,
  sources jsonb not null default '[]'::jsonb,
  contact_route text
);
comment on table kafaa_organisations is '[M09] Organisations: ENEC entities, partners, suppliers, universities, regulators';

-- M09 · Agreements (contract, JV, MoU, LoI ...) with public sources
create table if not exists kafaa_agreements (
  id text primary key,
  org_id text not null,
  type text not null check (type in ('contract', 'jv', 'mou', 'loi', 'framework', 'agreement', 'loan', 'membership', 'provider', 'shareholder', 'partnership', 'regulator', 'exercise', 'historic', 'proposal', 'supply', 'sca')),
  title_en text not null,
  title_ar text not null,
  binding boolean not null default false,
  signed text not null default '',
  status text not null default 'active' check (status in ('active', 'historic', 'exploratory')),
  sources jsonb not null default '[]'::jsonb
);
comment on table kafaa_agreements is '[M09] Agreements (contract, JV, MoU, LoI ...) with public sources';

-- M14 · Person: minimal profile (synthetic demo tenant)
create table if not exists kafaa_people (
  id text primary key,
  persona_id text unique,
  display_name text not null,
  display_name_ar text not null default '',
  initials text not null default '',
  kind text not null check (kind in ('staff', 'contractor', 'applicant', 'partner', 'observer', 'external')),
  entity_id text,
  org_id text,
  job_role_id text,
  job_family_id text,
  team_id text,
  crew text,
  unit text,
  level text check (level in ('entry', 'professional', 'senior', 'leadership')),
  nationality_flag text not null default 'unknown' check (nationality_flag in ('uae', 'other', 'unknown')),
  gender text check (gender in ('f', 'm')),
  language text not null default 'en' check (language in ('en', 'ar')),
  digits text not null default 'latn' check (digits in ('latn', 'arab')),
  hire_date date,
  status text not null default 'active' check (status in ('active', 'leaver', 'candidate')),
  manager_id text,
  synthetic boolean not null default true,
  notes text
);
comment on table kafaa_people is '[M14] Person: minimal profile (synthetic demo tenant)';

-- M14 · Role assignment: platform role + scope per person
create table if not exists kafaa_role_assignments (
  id text primary key,
  person_id text not null,
  role text not null,
  org_id text,
  scope_type text not null default 'self' check (scope_type in ('all', 'entity', 'family', 'team', 'crew', 'org', 'self')),
  scope_value text,
  granted_by text,
  granted_at timestamptz not null default now(),
  expires_at date,
  status text not null default 'active' check (status in ('active', 'pending_second', 'revoked')),
  second_approver text,
  reviewed_at timestamptz,
  reviewed_by text,
  review_note text,
  constraint kafaa_role_assignments_role_chk check (role in ('public', 'applicant', 'employee', 'licensed_operator', 'manager', 'instructor', 'training_manager', 'licensing_coord', 'hr_analyst', 'hr_director', 'partner_user', 'partner_admin', 'university', 'observer', 'editor', 'ecp_officer', 'admin', 'auditor'))
);
comment on table kafaa_role_assignments is '[M14] Role assignment: platform role + scope per person';

